        [" (fail-safe)"] = [" (Sicherheitswert)", " (sécurité)", " (güvenlik)", " (аварийное значение)"],
        ["No readable temperature sensors found. Missing keys trigger fail-safe."] = ["Keine lesbaren Temperatursensoren gefunden. Fehlende Schlüssel lösen den Sicherheitswert aus.", "Aucun capteur de température lisible trouvé. Les clés manquantes déclenchent les valeurs de sécurité.", "Okunabilir sıcaklık sensörü bulunamadı. Eksik anahtarlar güvenlik değerini tetikler.", "Читаемые датчики температуры не найдены. Отсутствующие ключи вызывают аварийные значения."],
        ["Hardware fan control stopped; safety frame requested; display stays connected."] = ["Physische Lüfterregelung gestoppt; Sicherheitswerte angefordert; Display bleibt verbunden.", "Contrôle physique arrêté ; valeurs de sécurité demandées ; l’écran reste connecté.", "Fiziksel fan denetimi durduruldu; güvenlik değerleri istendi; ekran bağlı kalır.", "Физическое управление остановлено; запрошены безопасные значения; дисплей остаётся подключён."],
        ["LIVE SERIAL FAN CONTROL ACTIVE: four channels, 2-second loop, fail-safe enabled."] = ["SERIELLE LÜFTERREGELUNG AKTIV: vier Kanäle, 2-Sekunden-Zyklus, Sicherheitswerte aktiviert.", "CONTRÔLE SÉRIE ACTIF : quatre canaux, cycle de 2 secondes, sécurité activée.", "CANLI SERİ FAN DENETİMİ ETKİN: dört kanal, 2 saniyelik döngü, güvenlik etkin.", "ПОСЛЕДОВАТЕЛЬНОЕ УПРАВЛЕНИЕ АКТИВНО: четыре канала, цикл 2 секунды, аварийная защита включена."],
        ["VIRTUAL LIS2 FAN CONTROL: safe frame 100% sent first; four-channel regulation active; no physical port opened."] = ["VIRTUELLE LIS2-LÜFTERREGELUNG: Zuerst 100%-Sicherheitswerte gesendet; Vierkanalregelung aktiv; kein physischer Port geöffnet.", "CONTRÔLE VIRTUEL LIS2 : valeurs de sécurité à 100 % envoyées en premier ; régulation sur quatre canaux active ; aucun port physique ouvert.", "SANAL LIS2 FAN DENETİMİ: önce %100 güvenlik değerleri gönderildi; dört kanal etkin; fiziksel bağlantı noktası açılmadı.", "ВИРТУАЛЬНОЕ УПРАВЛЕНИЕ LIS2: сначала отправлены безопасные значения 100 %; регулирование четырёх каналов активно; физический порт не открыт."],
        ["Virtual fan session stopped; {0} simulated protocol writes; safety frame restored."] = ["Virtuelle Lüftersitzung gestoppt; {0} simulierte Schreibvorgänge; Sicherheitswerte wiederhergestellt.", "Session virtuelle arrêtée ; {0} écritures simulées ; valeurs de sécurité rétablies.", "Sanal fan oturumu durduruldu; {0} simüle edilmiş yazma; güvenlik değerleri geri yüklendi.", "Виртуальный сеанс вентиляторов остановлен; записей протокола: {0}; безопасные значения восстановлены."],
        ["Imported {0} pages, {1} glyphs; token not imported."] = ["{0} Seiten und {1} Zeichen importiert; Token nicht importiert.", "{0} pages et {1} caractères importés ; jeton non importé.", "{0} sayfa ve {1} karakter içe aktarıldı; belirteç aktarılmadı.", "Импортировано страниц: {0}, символов: {1}; токен не импортирован."],
